const PRODUCT_FRAGMENT = `#graphql
  fragment ProductFields on Product {
    id
    title
    handle
    status
    featuredImage { url altText }
    priceRangeV2 {
      minVariantPrice { amount currencyCode }
    }
    tags
    vendor
  }
`;

const PRODUCTS_QUERY = `#graphql
  ${PRODUCT_FRAGMENT}
  query GetProducts($first: Int!, $after: String) {
    products(first: $first, after: $after) {
      pageInfo { hasNextPage endCursor }
      edges { node { ...ProductFields } }
    }
  }
`;
```

## CURSOR PAGINATION (Complete Implementation)

```typescript
// Full cursor pagination — never use offset pagination for Shopify
export async function loader({ request }: LoaderFunctionArgs) {
  const { admin } = await authenticate.admin(request);
  const url = new URL(request.url);
  const after = url.searchParams.get("after") || null;
  const before = url.searchParams.get("before") || null;
  const direction = before ? "backward" : "forward";

  const query = direction === "forward"
    ? `query($first: Int!, $after: String) {
        products(first: $first, after: $after) {
          pageInfo { hasNextPage hasPreviousPage startCursor endCursor }
          edges { cursor node { id title } }
        }
      }`
    : `query($last: Int!, $before: String) {
        products(last: $last, before: $before) {
          pageInfo { hasNextPage hasPreviousPage startCursor endCursor }
          edges { cursor node { id title } }
        }
      }`;

  const variables = direction === "forward"
    ? { first: 25, after }
    : { last: 25, before };

  const resp = await admin.graphql(query, { variables });
  const { data } = await resp.json();
  return json({ products: data.products });
}
```

## KEY MUTATIONS FOR QUIZSNAP

