  variables: {
    basicCodeDiscount: {
      title: `QUIZ-${Date.now()}`,
      code: `QUIZ10-${Math.random().toString(36).slice(2, 8).toUpperCase()}`,
      startsAt: new Date().toISOString(),
      customerGets: {
        value: { percentage: 0.10 },
        items: { allItems: true }
      },
      customerSelection: { allCustomers: true }
    }
  }
});
const { data } = await resp.json();
if (data.discountCodeBasicCreate.userErrors.length > 0) {
  throw new Error(data.discountCodeBasicCreate.userErrors[0].message);
}
