## GID HELPERS

```typescript
// app/utils/gid.ts
export function encodeGid(type: string, id: string | number): string {
  return `gid://shopify/${type}/${id}`;
}

export function decodeGid(gid: string): { type: string; id: string } {
  const parts = gid.split("/");
  return { type: parts[parts.length - 2], id: parts[parts.length - 1] };
}

export function extractId(gid: string): string {
  return gid.split("/").pop() ?? gid;
}

// Usage
const productGid = encodeGid("Product", "123456");         // gid://shopify/Product/123456
const { id } = decodeGid("gid://shopify/Product/123456");  // "123456"
```

## RATE LIMIT HANDLER (Exponential Backoff)

```typescript
// app/utils/graphql-with-retry.ts
export async function graphqlWithRetry(
  admin: AdminApiContext,
  query: string,
  variables: Record<string, unknown>,
  maxRetries = 3
): Promise<unknown> {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    const resp = await admin.graphql(query, { variables });
    const json = await resp.json();

    // Check throttle extension
    if (json.extensions?.cost) {
      const { actualQueryCost, throttleStatus } = json.extensions.cost;
      const { currentlyAvailable, restoreRate } = throttleStatus;
      if (currentlyAvailable < actualQueryCost * 2) {
        const waitMs = Math.ceil((actualQueryCost - currentlyAvailable) / restoreRate) * 1000;
        await new Promise(r => setTimeout(r, Math.min(waitMs, 10_000)));
      }
    }

    if (json.errors?.[0]?.extensions?.code === "THROTTLED") {
      const backoff = Math.pow(2, attempt) * 1000;
      await new Promise(r => setTimeout(r, backoff));
      continue;
    }

    return json;
  }
  throw new Error("GraphQL request failed after max retries");
}
```

## SPAWN AGENTS
- `product-sync` — when syncing product data from GraphQL to Prisma
- `order-attribution-builder` — when querying orders for attribution
- `metafield-builder` — when reading/writing metafields via GraphQL
- `discount-validator` — when working with discount mutations

## SELF-VALIDATION CHECKLIST
- [ ] Using `admin.graphql()` pattern (not raw fetch)
- [ ] All queries have `#graphql` template literal tag
- [ ] Checking `userErrors` array on all mutations
- [ ] Cursor-based pagination (not offset)
- [ ] GIDs properly formatted (`gid://shopify/Type/id`)
- [ ] Variables passed as second argument object `{ variables: {} }`
- [ ] Rate limit retry logic for production mutations
- [ ] `pageInfo` includes `startCursor`, `endCursor`, `hasNextPage`, `hasPreviousPage`
- [ ] Fragments used for repeated field selections
- [ ] `response.json()` called and `data.errors` checked

## NEVER
- Never use offset-based pagination for Shopify GraphQL (use cursors)
- Never ignore `userErrors` — HTTP 200 does not mean success
- Never hardcode GIDs as plain integers without the `gid://shopify/` prefix
- Never fetch more than 250 nodes in a single connection request
- Never retry GraphQL errors that are not THROTTLED (bad query = fix it)

