# Form Validator — Zod + Polaris Error States

## AUTO-DETECT TRIGGERS
- User mentions: validation, zod, form errors, required field, sanitize, validate
- Creating/editing forms with TextField, Select, Checkbox
- Action functions that process form data from FormData
- Error: "invalid_type", "too_small", ZodError instances

## DECISION TREE
```
Building a form? →
  Define Zod schema first (server-side source of truth)
  Add client-side mirror for UX (optional, derived from same schema)
  Server action validates with schema.safeParse(formData)
  Return field errors as flat object { fieldName: "message" }
  Polaris TextField receives error prop from useActionData()
```

## ZOD SCHEMA LIBRARY FOR QUIZSNAP

```typescript
// app/schemas/quiz.schema.ts
import { z } from "zod";

export const quizCreateSchema = z.object({
  title: z.string()
    .min(3, "Title must be at least 3 characters")
    .max(100, "Title cannot exceed 100 characters")
    .trim(),
  description: z.string()
    .max(500, "Description cannot exceed 500 characters")
    .trim()
    .optional(),
  status: z.enum(["DRAFT", "PUBLISHED", "ARCHIVED"], {
    errorMap: () => ({ message: "Status must be Draft, Published, or Archived" })
  }),
  coverImageUrl: z.string().url("Must be a valid URL").optional().or(z.literal("")),
  primaryColor: z.string()
    .regex(/^#[0-9A-Fa-f]{6}$/, "Must be a valid hex color (e.g. #FF5733)")
    .optional(),
  redirectUrl: z.string().url("Must be a valid URL").optional().or(z.literal("")),
  emailCaptureEnabled: z.boolean().default(false),
  emailCaptureLabel: z.string().max(100).trim().optional(),
});

export const questionSchema = z.object({
  text: z.string()
    .min(5, "Question must be at least 5 characters")
    .max(500, "Question cannot exceed 500 characters")
    .trim(),
  type: z.enum(["SINGLE_CHOICE", "MULTIPLE_CHOICE", "TEXT_INPUT", "IMAGE_CHOICE", "RATING", "SLIDER"]),
  required: z.boolean().default(true),
  helpText: z.string().max(200).trim().optional(),
  minValue: z.number().min(0).max(100).optional(),
  maxValue: z.number().min(0).max(100).optional(),
}).refine(
  (data) => {
    if (data.type === "SLIDER" || data.type === "RATING") {
      return data.minValue !== undefined && data.maxValue !== undefined;
    }
    return true;
  },
  { message: "Min and max values required for slider/rating questions", path: ["minValue"] }
);

export const answerSchema = z.object({
  text: z.string().min(1, "Answer text is required").max(200).trim(),
  imageUrl: z.string().url("Must be a valid image URL").optional().or(z.literal("")),
  weight: z.number().min(0).max(100).default(1),
  skipToQuestion: z.string().optional(),
});

export const integrationSettingsSchema = z.object({
  klaviyoApiKey: z.string()
    .regex(/^pk_[a-zA-Z0-9]+$/, "Must be a valid Klaviyo public API key (starts with pk_)")
    .optional()
    .or(z.literal("")),
  klaviyoListId: z.string().max(50).optional(),
  webhookUrl: z.string().url("Must be a valid HTTPS URL")
    .refine(url => url.startsWith("https://"), "Webhook URL must use HTTPS")
    .optional()
    .or(z.literal("")),
  notifyEmail: z.string().email("Must be a valid email address").optional().or(z.literal("")),
});

export type QuizCreateInput = z.infer<typeof quizCreateSchema>;
export type QuestionInput = z.infer<typeof questionSchema>;
export type AnswerInput = z.infer<typeof answerSchema>;
export type IntegrationSettingsInput = z.infer<typeof integrationSettingsSchema>;
```

## SERVER-SIDE VALIDATION IN ACTIONS

```typescript
// app/routes/app.quizzes.new.tsx
import { json, redirect } from "@remix-run/node";
import type { ActionFunctionArgs } from "@remix-run/node";
import { authenticate } from "~/shopify.server";
import { quizCreateSchema } from "~/schemas/quiz.schema";
import { db } from "~/db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();

  const raw = {
    title: formData.get("title"),
    description: formData.get("description"),
    status: formData.get("status"),
    coverImageUrl: formData.get("coverImageUrl"),
    primaryColor: formData.get("primaryColor"),
    emailCaptureEnabled: formData.get("emailCaptureEnabled") === "true",
    redirectUrl: formData.get("redirectUrl"),
  };

  const result = quizCreateSchema.safeParse(raw);

  if (!result.success) {
    const fieldErrors = result.error.flatten().fieldErrors;
    // Return flat { field: firstMessage } for Polaris error props
    const errors = Object.fromEntries(
      Object.entries(fieldErrors).map(([k, v]) => [k, v?.[0] ?? "Invalid value"])
    );
    return json({ errors, values: raw }, { status: 422 });
  }

  const quiz = await db.quiz.create({
    data: { ...result.data, shop: session.shop }
  });

  return redirect(`/app/quizzes/${quiz.id}/edit`);
}
```

## CLIENT-SIDE ERROR DISPLAY WITH POLARIS

```typescript
// app/components/QuizForm.tsx
import { useActionData, useNavigation } from "@remix-run/react";
import { Form } from "@remix-run/react";
import { TextField, Select, Button, FormLayout, Banner } from "@shopify/polaris";

interface ActionData {
  errors?: Record<string, string>;
  values?: Record<string, unknown>;
}

export function QuizForm() {
  const actionData = useActionData<ActionData>();
  const navigation = useNavigation();
  const isSubmitting = navigation.state === "submitting";
  const errors = actionData?.errors ?? {};

  return (
    <Form method="post">
      <FormLayout>
        {Object.keys(errors).length > 0 && (
          <Banner tone="critical" title="Please fix the following errors">
            <ul>
              {Object.entries(errors).map(([field, msg]) => (
                <li key={field}>{msg}</li>
              ))}
            </ul>
          </Banner>
        )}

        <TextField
          label="Quiz Title"
          name="title"
          defaultValue={String(actionData?.values?.title ?? "")}
          error={errors.title}
          autoComplete="off"
          requiredIndicator
        />

        <TextField
          label="Description"
          name="description"
          defaultValue={String(actionData?.values?.description ?? "")}
          error={errors.description}
          multiline={3}
          autoComplete="off"
        />

        <Select
          label="Status"
          name="status"
          options={[
            { label: "Draft", value: "DRAFT" },
            { label: "Published", value: "PUBLISHED" },
          ]}
          error={errors.status}
        />

        <Button submit loading={isSubmitting} variant="primary">
          {isSubmitting ? "Creating..." : "Create Quiz"}
        </Button>
      </FormLayout>
    </Form>
  );
}
```

