## PRISMA CURSOR PAGINATION PATTERN

```typescript
// app/routes/app.responses.tsx
import type { LoaderFunctionArgs } from "@remix-run/node";
import { json } from "@remix-run/node";
import { authenticate } from "~/shopify.server";
import { db } from "~/db.server";

const PAGE_SIZE = 25;

export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const url = new URL(request.url);
  const afterCursor = url.searchParams.get("after");
  const beforeCursor = url.searchParams.get("before");
  const pageSize = Math.min(Number(url.searchParams.get("pageSize") ?? PAGE_SIZE), 100);

  // Forward pagination
  if (afterCursor || (!afterCursor && !beforeCursor)) {
    const items = await db.quizResponse.findMany({
      where: { quiz: { shop: session.shop } },
      take: pageSize + 1,            // +1 to detect if there's a next page
      skip: afterCursor ? 1 : 0,     // skip the cursor itself
      cursor: afterCursor ? { id: afterCursor } : undefined,
      orderBy: { createdAt: "desc" },
      include: { quiz: { select: { title: true } } },
    });

    const hasNextPage = items.length > pageSize;
    const results = hasNextPage ? items.slice(0, pageSize) : items;
    const endCursor = results[results.length - 1]?.id;
    const startCursor = results[0]?.id;

    // Get total count for display (cached, not live for performance)
    const totalCount = await db.quizResponse.count({
      where: { quiz: { shop: session.shop } }
    });

    return json({
      responses: results,
      pageInfo: {
        hasNextPage,
        hasPreviousPage: !!afterCursor,
        startCursor,
        endCursor,
      },
      totalCount,
    });
  }

  // Backward pagination
  const items = await db.quizResponse.findMany({
    where: { quiz: { shop: session.shop } },
    take: -(pageSize + 1),
    skip: 1,
    cursor: { id: beforeCursor! },
    orderBy: { createdAt: "desc" },
    include: { quiz: { select: { title: true } } },
  });

  const hasPreviousPage = items.length > pageSize;
  const results = hasPreviousPage ? items.slice(1) : items;

  return json({
    responses: results,
    pageInfo: {
      hasNextPage: true,
      hasPreviousPage,
      startCursor: results[0]?.id,
      endCursor: results[results.length - 1]?.id,
    },
    totalCount: 0,
  });
}
```

