export function PaginationControls({ pageInfo, totalCount, currentCount }: Props) {
  const navigate = useNavigate();
  const location = useLocation();

  function buildUrl(cursor: string, direction: "next" | "prev"): string {
    const params = new URLSearchParams(location.search);
    params.delete("after");
    params.delete("before");
    if (direction === "next") params.set("after", cursor);
    else params.set("before", cursor);
    return `${location.pathname}?${params.toString()}`;
  }

  return (
    <Box paddingBlockStart="400" paddingBlockEnd="200">
      <InlineStack align="center" gap="400">
        <Text as="p" variant="bodySm" tone="subdued">
          Showing {currentCount} of {totalCount.toLocaleString()} responses
        </Text>
        <Pagination
          hasPrevious={pageInfo.hasPreviousPage}
          hasNext={pageInfo.hasNextPage}
          onPrevious={() => {
            if (pageInfo.startCursor) navigate(buildUrl(pageInfo.startCursor, "prev"));
          }}
          onNext={() => {
            if (pageInfo.endCursor) navigate(buildUrl(pageInfo.endCursor, "next"));
          }}
          label={`${currentCount} items`}
        />
      </InlineStack>
    </Box>
  );
}
