## LOAD MORE PATTERN (Storefront / Mobile)

```typescript
// For storefront quiz result history or infinite scroll
import { useFetcher } from "@remix-run/react";
import { useEffect, useRef, useState } from "react";

export function useInfiniteScroll<T>(initialData: T[], initialCursor?: string) {
  const fetcher = useFetcher<{ items: T[]; nextCursor?: string }>();
  const [allItems, setAllItems] = useState<T[]>(initialData);
  const [cursor, setCursor] = useState<string | undefined>(initialCursor);
  const sentinelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (fetcher.data) {
      setAllItems(prev => [...prev, ...(fetcher.data?.items ?? [])]);
      setCursor(fetcher.data?.nextCursor);
    }
  }, [fetcher.data]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && cursor && fetcher.state === "idle") {
          fetcher.load(`?after=${cursor}`);
        }
      },
      { threshold: 0.1 }
    );
    if (sentinelRef.current) observer.observe(sentinelRef.current);
    return () => observer.disconnect();
  }, [cursor, fetcher]);

  return { allItems, sentinelRef, isLoading: fetcher.state === "loading", hasMore: !!cursor };
}
