// app/utils/filters.ts
export interface QuizFilters {
  search: string;
  status: string;
  sortKey: string;
  sortDir: "asc" | "desc";
}

export function getFiltersFromURL(request: Request): QuizFilters {
  const url = new URL(request.url);
  return {
    search: url.searchParams.get("search") ?? "",
    status: url.searchParams.get("status") ?? "all",
    sortKey: url.searchParams.get("sort") ?? "createdAt",
    sortDir: (url.searchParams.get("dir") ?? "desc") as "asc" | "desc",
  };
}

export function buildFilteredQuery(filters: QuizFilters) {
  const where: Record<string, unknown> = {};

  if (filters.search) {
    where.title = { contains: filters.search, mode: "insensitive" };
  }

  if (filters.status !== "all") {
    where.status = filters.status.toUpperCase();
  }

  const orderBy = { [filters.sortKey]: filters.sortDir };

  return { where, orderBy };
}
