export function QuizFilters({ currentFilters }: { currentFilters: Record<string, string> }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [status, setStatus] = useState<string[]>(
    currentFilters.status !== "all" ? [currentFilters.status] : []
  );

  function updateFilter(key: string, value: string | null) {
    const params = new URLSearchParams(location.search);
    if (value) params.set(key, value);
    else params.delete(key);
    params.delete("after");
    params.delete("before");
    navigate(`${location.pathname}?${params.toString()}`, { replace: true });
  }

  const appliedFilters: ActiveFilter[] = [];
  if (status.length > 0) {
    appliedFilters.push({
      key: "status",
      label: `Status: ${status[0]}`,
      onRemove: () => {
        setStatus([]);
        updateFilter("status", null);
      },
    });
  }

  return (
    <Filters
      queryValue={currentFilters.search}
      queryPlaceholder="Search quizzes..."
      onQueryChange={(val) => updateFilter("search", val || null)}
      onQueryClear={() => updateFilter("search", null)}
      filters={[
        {
          key: "status",
          label: "Status",
          filter: (
            <ChoiceList
              title="Status"
              titleHidden
              choices={[
                { label: "Draft", value: "DRAFT" },
                { label: "Published", value: "PUBLISHED" },
                { label: "Archived", value: "ARCHIVED" },
              ]}
              selected={status}
              onChange={(selected) => {
                setStatus(selected);
                updateFilter("status", selected[0] ?? null);
              }}
            />
          ),
          shortcut: true,
        },
      ]}
      appliedFilters={appliedFilters}
      onClearAll={() => {
        setStatus([]);
        const params = new URLSearchParams();
        navigate(`${location.pathname}?${params.toString()}`, { replace: true });
      }}
    />
  );
}
