// app/routes/app.quizzes.tsx (client component portion)
import {
  IndexTable,
  useIndexResourceState,
  Button,
  Badge,
  Text,
  Thumbnail,
  InlineStack,
} from "@shopify/polaris";
import { useCallback, useState } from "react";
import { useFetcher } from "@remix-run/react";

interface Quiz {
  id: string;
  title: string;
  status: string;
  responseCount: number;
  createdAt: string;
}

export function QuizIndexTable({ quizzes }: { quizzes: Quiz[] }) {
  const resourceName = { singular: "quiz", plural: "quizzes" };
  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(quizzes);
  const [confirmAction, setConfirmAction] = useState<{ type: string; ids: string[] } | null>(null);
  const fetcher = useFetcher();

  const bulkActions = [
    {
      content: "Publish",
      onAction: () => handleBulkAction("publish", selectedResources),
    },
    {
      content: "Archive",
      onAction: () => handleBulkAction("archive", selectedResources),
    },
    {
      destructive: true,
      content: "Delete",
      onAction: () => setConfirmAction({ type: "delete", ids: selectedResources }),
    },
  ];

  const promotedBulkActions = [
    {
      content: "Export CSV",
      onAction: () => handleBulkAction("export", selectedResources),
    },
  ];

  function handleBulkAction(type: string, ids: string[]) {
    if (type === "delete") {
      setConfirmAction({ type, ids });
      return;
    }
    fetcher.submit(
      { _action: "bulk", operation: type, ids: JSON.stringify(ids) },
      { method: "POST" }
    );
  }

  const rows = quizzes.map(({ id, title, status, responseCount, createdAt }) => (
    <IndexTable.Row id={id} key={id} selected={selectedResources.includes(id)}>
      <IndexTable.Cell>
        <Text variant="bodyMd" fontWeight="bold" as="span">{title}</Text>
      </IndexTable.Cell>
      <IndexTable.Cell>
        <Badge tone={status === "PUBLISHED" ? "success" : status === "ARCHIVED" ? "subdued" : "info"}>
          {status}
        </Badge>
      </IndexTable.Cell>
      <IndexTable.Cell>{responseCount.toLocaleString()}</IndexTable.Cell>
      <IndexTable.Cell>{new Date(createdAt).toLocaleDateString()}</IndexTable.Cell>
    </IndexTable.Row>
  ));

  return (
    <>
      <IndexTable
        resourceName={resourceName}
        itemCount={quizzes.length}
        selectedItemsCount={allResourcesSelected ? "All" : selectedResources.length}
        onSelectionChange={handleSelectionChange}
        headings={[
          { title: "Title" },
          { title: "Status" },
          { title: "Responses" },
          { title: "Created" },
        ]}
        bulkActions={bulkActions}
        promotedBulkActions={promotedBulkActions}
      >
        {rows}
      </IndexTable>

      {confirmAction && (
        <BulkDeleteConfirmModal
          count={confirmAction.ids.length}
          onConfirm={() => {
            fetcher.submit(
              { _action: "bulk", operation: "delete", ids: JSON.stringify(confirmAction.ids) },
              { method: "POST" }
            );
            setConfirmAction(null);
          }}
          onCancel={() => setConfirmAction(null)}
        />
      )}
    </>
