## BACKEND BULK ACTION HANDLER

```typescript
// In action function of app.quizzes.tsx
export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const actionType = formData.get("_action");

  if (actionType === "bulk") {
    const operation = String(formData.get("operation"));
    const ids = JSON.parse(String(formData.get("ids"))) as string[];

    // CRITICAL: Always scope to shop to prevent cross-tenant access
    const shopScope = { quiz: { shop: session.shop } };

    switch (operation) {
      case "delete":
        await db.quizResponse.deleteMany({ where: { ...shopScope, quizId: { in: ids } } });
        await db.quiz.deleteMany({
          where: { id: { in: ids }, shop: session.shop }
        });
        return json({ success: true, deleted: ids.length });

      case "publish":
        await db.quiz.updateMany({
          where: { id: { in: ids }, shop: session.shop },
          data: { status: "PUBLISHED", publishedAt: new Date() }
        });
        return json({ success: true, updated: ids.length });

      case "archive":
        await db.quiz.updateMany({
          where: { id: { in: ids }, shop: session.shop },
          data: { status: "ARCHIVED" }
        });
        return json({ success: true, updated: ids.length });

      default:
        return json({ error: "Unknown bulk operation" }, { status: 400 });
    }
  }

  return json({ error: "Invalid action" }, { status: 400 });
}
