## POLLING PATTERN (Analytics Auto-Refresh)

```typescript
// app/hooks/usePolling.ts
import { useRevalidator } from "@remix-run/react";
import { useEffect, useRef, useState } from "react";

export function usePolling(intervalMs = 30_000, enabled = true) {
  const { revalidate, state } = useRevalidator();
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const [lastRefreshed, setLastRefreshed] = useState(new Date());

  useEffect(() => {
    if (!enabled) return;
    intervalRef.current = setInterval(() => {
      if (state === "idle") {
        revalidate();
        setLastRefreshed(new Date());
      }
    }, intervalMs);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [intervalMs, enabled, state, revalidate]);

  function forceRefresh() {
    revalidate();
    setLastRefreshed(new Date());
  }

  return { lastRefreshed, isRefreshing: state === "loading", forceRefresh };
}

// Usage in analytics route
export function AnalyticsDashboard() {
  const { lastRefreshed, isRefreshing, forceRefresh } = usePolling(30_000);

  return (
    <div>
      <InlineStack align="space-between">
        <Text>Live Analytics</Text>
        <InlineStack gap="200">
          <Text tone="subdued" variant="bodySm">
            Updated {lastRefreshed.toLocaleTimeString()}
          </Text>
          <Button size="slim" onClick={forceRefresh} loading={isRefreshing}>
            Refresh
          </Button>
        </InlineStack>
      </InlineStack>
    </div>
  );
}
