## SERVER-SENT EVENTS (SSE) — Live Response Counter

```typescript
// app/routes/api.quiz.$quizId.stream.ts
import type { LoaderFunctionArgs } from "@remix-run/node";
import { authenticate } from "~/shopify.server";
import { db } from "~/db.server";

export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const { quizId } = params;

  // Verify ownership
  const quiz = await db.quiz.findFirst({
    where: { id: quizId, shop: session.shop }
  });
  if (!quiz) return new Response("Not Found", { status: 404 });

  const headers = new Headers({
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
    "Connection": "keep-alive",
    "X-Accel-Buffering": "no",
  });

  let isClosed = false;
  request.signal.addEventListener("abort", () => { isClosed = true; });

  const stream = new ReadableStream({
    async start(controller) {
      const encoder = new TextEncoder();

      function send(event: string, data: unknown) {
        if (!isClosed) {
          controller.enqueue(encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`));
        }
      }

      // Send initial count
      const count = await db.quizResponse.count({ where: { quizId } });
      send("count", { count });

      // Poll for updates every 5 seconds
      const interval = setInterval(async () => {
        if (isClosed) {
          clearInterval(interval);
          controller.close();
          return;
        }
        const newCount = await db.quizResponse.count({ where: { quizId } });
        send("count", { count: newCount, timestamp: Date.now() });
      }, 5_000);

      // Keepalive comment every 25s (prevents proxy timeouts)
      const keepalive = setInterval(() => {
        if (!isClosed) controller.enqueue(encoder.encode(": keepalive\n\n"));
      }, 25_000);

      request.signal.addEventListener("abort", () => {
        clearInterval(interval);
        clearInterval(keepalive);
        isClosed = true;
      });
    }
  });

  return new Response(stream, { headers });
}
```

## SSE CLIENT HOOK

```typescript
// app/hooks/useSSE.ts
import { useEffect, useRef, useState } from "react";

export function useSSE<T>(url: string, eventName: string, initial: T) {
  const [data, setData] = useState<T>(initial);
  const [connected, setConnected] = useState(false);
  const esRef = useRef<EventSource | null>(null);

  useEffect(() => {
    const es = new EventSource(url);
    esRef.current = es;

    es.addEventListener("open", () => setConnected(true));
    es.addEventListener("error", () => setConnected(false));
    es.addEventListener(eventName, (e: MessageEvent) => {
      try { setData(JSON.parse(e.data)); } catch {}
    });

    return () => es.close();
  }, [url, eventName]);

  return { data, connected };
}

// Usage in quiz detail page
export function LiveResponseCount({ quizId }: { quizId: string }) {
  const { data, connected } = useSSE<{ count: number }>(
    `/api/quiz/${quizId}/stream`,
    "count",
    { count: 0 }
  );

  return (
    <InlineStack gap="200" align="center">
      <div style={{
        width: 8, height: 8, borderRadius: "50%",
        background: connected ? "#00a651" : "#d72c0d"
      }} />
      <Text variant="headingLg">{data.count.toLocaleString()}</Text>
      <Text tone="subdued">responses</Text>
    </InlineStack>
  );
}
