// app/hooks/useOptimisticUpdate.ts
import { useFetcher } from "@remix-run/react";

export function useOptimisticQuizStatus(
  quizId: string,
  currentStatus: string
) {
  const fetcher = useFetcher<{ status: string }>();
  const optimisticStatus = fetcher.formData
    ? String(fetcher.formData.get("status"))
    : currentStatus;

  function toggleStatus() {
    const newStatus = currentStatus === "PUBLISHED" ? "DRAFT" : "PUBLISHED";
    fetcher.submit(
      { _action: "updateStatus", quizId, status: newStatus },
      { method: "POST", action: "/app/quizzes" }
    );
  }

  return {
    displayStatus: optimisticStatus,
    isUpdating: fetcher.state !== "idle",
    toggleStatus,
  };
}
