## DATA PREPARATION HELPERS

```typescript
// app/utils/chart-data.ts
export function groupResponsesByDay(
  responses: Array<{ createdAt: Date; completedAt: Date | null }>
): TimeSeriesPoint[] {
  const byDay = new Map<string, { started: number; completions: number }>();
  for (const r of responses) {
    const day = r.createdAt.toISOString().split("T")[0];
    const current = byDay.get(day) ?? { started: 0, completions: 0 };
    current.started++;
    if (r.completedAt) current.completions++;
    byDay.set(day, current);
  }
  return Array.from(byDay.entries())
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([date, vals]) => ({ date, ...vals }));
}
```

