## FEATURE CHECK FUNCTION

```typescript
// app/utils/feature-check.server.ts
import { db } from "~/db.server";
import { PLAN_FEATURES, type Plan, type FeatureSet } from "~/config/features";

export async function getShopFeatures(shop: string): Promise<{
  plan: Plan;
  features: FeatureSet;
  overrides: Partial<FeatureSet>;
}> {
  const subscription = await db.subscription.findUnique({
    where: { shop },
    select: { plan: true, featureOverrides: true }
  });

  const plan = (subscription?.plan ?? "FREE") as Plan;
  const overrides = (subscription?.featureOverrides as Partial<FeatureSet>) ?? {};
  const baseFeatures = PLAN_FEATURES[plan];

  return {
    plan,
    features: { ...baseFeatures, ...overrides },
    overrides,
  };
}

export async function checkFeature(
  shop: string,
  feature: keyof FeatureSet
): Promise<boolean> {
  const { features } = await getShopFeatures(shop);
  return Boolean(features[feature]);
}

export async function checkLimit(
  shop: string,
  limitKey: "maxQuizzes" | "maxQuestionsPerQuiz" | "maxResponsesPerMonth",
  currentCount: number
): Promise<{ allowed: boolean; limit: number; current: number }> {
  const { features } = await getShopFeatures(shop);
  const limit = features[limitKey] as number;
  return {
    allowed: currentCount < limit,
    limit,
    current: currentCount,
  };
}
```

