export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  // Internal admin only — check for admin shop
  if (session.shop !== process.env.ADMIN_SHOP) {
    throw new Response("Forbidden", { status: 403 });
  }

  const formData = await request.formData();
  const targetShop = String(formData.get("shop"));
  const feature = String(formData.get("feature")) as keyof FeatureSet;
  const enabled = formData.get("enabled") === "true";

  await db.subscription.update({
    where: { shop: targetShop },
    data: {
      featureOverrides: {
        // Merge with existing overrides
        ...(await db.subscription.findUnique({ where: { shop: targetShop } }))?.featureOverrides as object,
        [feature]: enabled,
      }
    }
  });

  return json({ success: true });
}
