## METAFIELD DEFINITIONS (Create Once at Install)

```typescript
// app/utils/metafield-setup.server.ts
import type { AdminApiContext } from "@shopify/shopify-app-remix/server";

const METAFIELD_DEFINITIONS = [
  {
    name: "Quiz Result",
    namespace: "quizsnap",
    key: "quiz_result",
    ownerType: "CUSTOMER",
    type: "json",
    description: "Last quiz result: {quizId, resultPage, score, completedAt}",
  },
  {
    name: "Recommended Products",
    namespace: "quizsnap",
    key: "recommended_product_ids",
    ownerType: "CUSTOMER",
    type: "list.product_reference",
    description: "Product GIDs recommended by last quiz completion",
  },
  {
    name: "Quiz Score",
    namespace: "quizsnap",
    key: "quiz_score",
    ownerType: "CUSTOMER",
    type: "number_integer",
    description: "Numeric quiz score from last completion",
  },
  {
    name: "Quiz Attribution",
    namespace: "quizsnap",
    key: "quiz_id",
    ownerType: "ORDER",
    type: "single_line_text_field",
    description: "QuizSnap quiz ID that led to this order",
  },
];

export async function ensureMetafieldDefinitions(admin: AdminApiContext) {
  for (const def of METAFIELD_DEFINITIONS) {
    const resp = await admin.graphql(
      `#graphql
      mutation metafieldDefinitionCreate($definition: MetafieldDefinitionInput!) {
        metafieldDefinitionCreate(definition: $definition) {
          createdDefinition { id name }
          userErrors { field message code }
        }
      }`,
      { variables: { definition: def } }
    );
    const { data } = await resp.json();
    const errors = data.metafieldDefinitionCreate.userErrors;
    // TAKEN = already exists, not a real error
    if (errors.length > 0 && errors[0].code !== "TAKEN") {
      console.error("Metafield definition error:", errors[0].message);
    }
  }
}
