## WRITE CUSTOMER METAFIELDS (After Quiz Completion)

```typescript
// app/utils/metafields.server.ts
interface QuizResult {
  quizId: string;
  quizTitle: string;
  resultPageTitle: string;
  score: number;
  recommendedProductGids: string[];
  completedAt: string;
}

export async function saveQuizResultToCustomer(
  admin: AdminApiContext,
  customerGid: string,
  result: QuizResult
): Promise<void> {
  const metafields = [
    {
      ownerId: customerGid,
      namespace: "quizsnap",
      key: "quiz_result",
      type: "json",
      value: JSON.stringify({
        quizId: result.quizId,
        quizTitle: result.quizTitle,
        resultPage: result.resultPageTitle,
        score: result.score,
        completedAt: result.completedAt,
      }),
    },
    {
      ownerId: customerGid,
      namespace: "quizsnap",
      key: "quiz_score",
      type: "number_integer",
      value: String(result.score),
    },
    {
      ownerId: customerGid,
      namespace: "quizsnap",
      key: "recommended_product_ids",
      type: "list.product_reference",
      value: JSON.stringify(result.recommendedProductGids),
    },
  ];

  const resp = await admin.graphql(
    `#graphql
    mutation metafieldsSet($metafields: [MetafieldsSetInput!]!) {
      metafieldsSet(metafields: $metafields) {
        metafields { key namespace value }
        userErrors { field message }
      }
    }`,
    { variables: { metafields } }
  );

  const { data } = await resp.json();
  if (data.metafieldsSet.userErrors.length > 0) {
    throw new Error(`Metafield write failed: ${data.metafieldsSet.userErrors[0].message}`);
  }
}
