## CHECKOUT ATTRIBUTE INJECTION

```typescript
// extensions/quiz-attribution/src/index.tsx
import {
  extension,
  useApplyAttributeChange,
  useSettings,
  useEffect,
} from "@shopify/ui-extensions-react/checkout";

export default extension("purchase.checkout.cart-line-list.render-after", (root, api) => {
  root.render(<QuizAttributionInjector />);
});

function QuizAttributionInjector() {
  const applyAttributeChange = useApplyAttributeChange();

  // Read quiz session from localStorage (set by storefront quiz)
  useEffect(() => {
    if (typeof window === "undefined") return;
    const quizSession = window.sessionStorage.getItem("quizsnap_session");
    if (!quizSession) return;

    try {
      const { quizId, responseId } = JSON.parse(quizSession);
      applyAttributeChange({
        type: "updateAttribute",
        key: "_quizsnap_quiz_id",
        value: quizId,
      });
      applyAttributeChange({
        type: "updateAttribute",
        key: "_quizsnap_response_id",
        value: responseId,
      });
    } catch {}
  }, []);

  return null; // Invisible — only injects attributes
}
```

