// app/routes/webhooks.orders.create.tsx
import type { ActionFunctionArgs } from "@remix-run/node";
import { authenticate } from "~/shopify.server";
import { db } from "~/db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop, payload } = await authenticate.webhook(request);
  if (topic !== "ORDERS_CREATE") return new Response("OK");

  const order = payload as ShopifyOrder;
  await attributeOrderToQuiz(shop, order);

  return new Response("OK");
}

interface ShopifyOrder {
  id: number;
  name: string;
  total_price: string;
  currency: string;
  cart_token?: string;
  customer?: { id: number; email: string };
  note_attributes: Array<{ name: string; value: string }>;
}

async function attributeOrderToQuiz(shop: string, order: ShopifyOrder) {
  const orderGid = `gid://shopify/Order/${order.id}`;

  // Strategy 1: Order attribute from checkout extension
  const quizIdAttr = order.note_attributes.find(a => a.name === "_quizsnap_quiz_id");
  const responseIdAttr = order.note_attributes.find(a => a.name === "_quizsnap_response_id");

  if (quizIdAttr?.value) {
    await createAttribution(shop, {
      orderId: orderGid,
      orderName: order.name,
      orderTotal: parseFloat(order.total_price),
      currency: order.currency,
      quizId: quizIdAttr.value,
      quizResponseId: responseIdAttr?.value,
      customerId: order.customer ? `gid://shopify/Customer/${order.customer.id}` : undefined,
      customerEmail: order.customer?.email,
      attributionType: "ORDER_ATTRIBUTE",
    });
    return;
  }

  // Strategy 2: Cart token match (7-day window)
  if (order.cart_token) {
    const windowStart = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
    const response = await db.quizResponse.findFirst({
      where: {
        cartToken: order.cart_token,
        quiz: { shop },
        completedAt: { gte: windowStart },
      },
      include: { quiz: { select: { id: true } } }
    });

    if (response) {
      await createAttribution(shop, {
        orderId: orderGid,
        orderName: order.name,
        orderTotal: parseFloat(order.total_price),
        currency: order.currency,
        quizId: response.quiz.id,
        quizResponseId: response.id,
        customerId: order.customer ? `gid://shopify/Customer/${order.customer.id}` : undefined,
        customerEmail: order.customer?.email,
        attributionType: "CART_TOKEN",
      });
      return;
    }
  }

  // Strategy 3: Email match (24-hour window)
  if (order.customer?.email) {
    const windowStart = new Date(Date.now() - 24 * 60 * 60 * 1000);
    const response = await db.quizResponse.findFirst({
      where: {
        email: order.customer.email,
        quiz: { shop },
        completedAt: { gte: windowStart },
      },
      include: { quiz: { select: { id: true } } },
      orderBy: { completedAt: "desc" },
    });

    if (response) {
      await createAttribution(shop, {
        orderId: orderGid,
        orderName: order.name,
        orderTotal: parseFloat(order.total_price),
        currency: order.currency,
        quizId: response.quiz.id,
        quizResponseId: response.id,
        customerId: `gid://shopify/Customer/${order.customer.id}`,
        customerEmail: order.customer.email,
        attributionType: "EMAIL_MATCH",
      });
    }
  }
}

async function createAttribution(shop: string, data: Omit<OrderAttribution, "id" | "attributedAt">) {
  await db.orderAttribution.upsert({
    where: { shop_orderId: { shop, orderId: data.orderId } },
    create: { shop, ...data },
    update: {}, // Don't overwrite existing attribution
  });
}
