## REVENUE REPORTING QUERIES

```typescript
// app/utils/attribution-queries.server.ts
export async function getQuizAttributedRevenue(
  shop: string,
  quizId?: string,
  dateFrom?: Date,
  dateTo?: Date
): Promise<{
  totalRevenue: number;
  orderCount: number;
  currency: string;
  byQuiz: Array<{ quizId: string; quizTitle: string; revenue: number; orders: number }>;
}> {
  const where = {
    shop,
    ...(quizId && { quizId }),
    ...(dateFrom && { attributedAt: { gte: dateFrom } }),
    ...(dateTo && { attributedAt: { lte: dateTo } }),
  };

  const [aggregates, byQuiz] = await Promise.all([
    db.orderAttribution.aggregate({
      where,
      _sum: { orderTotal: true },
      _count: { id: true },
    }),
    db.orderAttribution.groupBy({
      by: ["quizId"],
      where,
      _sum: { orderTotal: true },
      _count: { id: true },
    }),
  ]);

  // Enrich with quiz titles
  const quizIds = byQuiz.map(b => b.quizId);
  const quizTitles = await db.quiz.findMany({
    where: { id: { in: quizIds } },
    select: { id: true, title: true },
  });
  const titleMap = new Map(quizTitles.map(q => [q.id, q.title]));

  return {
    totalRevenue: aggregates._sum.orderTotal ?? 0,
    orderCount: aggregates._count.id,
    currency: "USD", // Get from shop settings
    byQuiz: byQuiz.map(b => ({
      quizId: b.quizId,
      quizTitle: titleMap.get(b.quizId) ?? "Unknown",
      revenue: b._sum.orderTotal ?? 0,
      orders: b._count.id,
    })),
  };
}
