```typescript
// app/components/storefront/VariantSelector.tsx
import { useState, useMemo, useCallback } from "react";
import type { ProductVariant, ProductOption } from "~/types/product";

interface Props {
  options: ProductOption[];
  variants: ProductVariant[];
  onVariantChange: (variant: ProductVariant | null) => void;
}

export function VariantSelector({ options, variants, onVariantChange }: Props) {
  const [selectedOptions, setSelectedOptions] = useState<Record<string, string>>(
    // Pre-select first available combination
    () => {
      const firstAvailable = variants.find(v => v.availableForSale);
      if (!firstAvailable) return {};
      return Object.fromEntries(
        firstAvailable.selectedOptions.map(o => [o.name, o.value])
      );
    }
  );

  const selectedVariant = useMemo(() => {
    return variants.find(v =>
      v.selectedOptions.every(o => selectedOptions[o.name] === o.value)
    ) ?? null;
  }, [variants, selectedOptions]);

  const handleOptionChange = useCallback((optionName: string, value: string) => {
    const newOptions = { ...selectedOptions, [optionName]: value };
    setSelectedOptions(newOptions);
    const variant = variants.find(v =>
      v.selectedOptions.every(o => newOptions[o.name] === o.value)
    );
    onVariantChange(variant ?? null);
  }, [selectedOptions, variants, onVariantChange]);

  function isOptionAvailable(optionName: string, value: string): boolean {
    const testOptions = { ...selectedOptions, [optionName]: value };
    return variants.some(v =>
      v.availableForSale &&
      v.selectedOptions.every(o => testOptions[o.name] === o.value)
    );
  }

  return (
    <div className="variant-selector">
      {options.map(option => (
        <div key={option.name} className="option-group">
          <p className="option-label">
            {option.name}:
            {selectedOptions[option.name] && (
              <span className="option-selected-value"> {selectedOptions[option.name]}</span>
            )}
          </p>
          {option.name.toLowerCase() === "color" ? (
            <ColorSwatches
              values={option.values}
              selected={selectedOptions[option.name]}
              onSelect={(val) => handleOptionChange(option.name, val)}
              isAvailable={(val) => isOptionAvailable(option.name, val)}
            />
          ) : (
            <SizeButtons
              values={option.values}
              selected={selectedOptions[option.name]}
              onSelect={(val) => handleOptionChange(option.name, val)}
              isAvailable={(val) => isOptionAvailable(option.name, val)}
            />
          )}
        </div>
      ))}
    </div>
  );
}
