## ADD TO CART WITH VARIANT VALIDATION

```typescript
// app/components/storefront/AddToCartButton.tsx
import { useState } from "react";

interface Props {
  productId: string;
  selectedVariant: ProductVariant | null;
  storeDomain: string;
}

export function AddToCartButton({ productId, selectedVariant, storeDomain }: Props) {
  const [adding, setAdding] = useState(false);
  const [added, setAdded] = useState(false);

  const isUnavailable = selectedVariant && !selectedVariant.availableForSale;
  const needsSelection = !selectedVariant;

  async function handleAddToCart() {
    if (!selectedVariant || isUnavailable) return;
    setAdding(true);

    try {
      await fetch(`https://${storeDomain}/cart/add.js`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: selectedVariant.id.split("/").pop(), quantity: 1 }),
      });
      setAdded(true);
      setTimeout(() => setAdded(false), 2500);
    } finally {
      setAdding(false);
    }
  }

  const buttonText = adding ? "Adding..." : added ? "Added!" :
    isUnavailable ? "Sold Out" :
    needsSelection ? "Select Options" : "Add to Cart";

  return (
    <button
      onClick={handleAddToCart}
      disabled={adding || isUnavailable || needsSelection}
      style={{
        width: "100%", padding: "12px 20px",
        borderRadius: 6, border: "none",
        background: isUnavailable || needsSelection ? "#c4cdd5" : added ? "#00A651" : "#5C6AC4",
        color: "white", fontWeight: 600, fontSize: 15,
        cursor: isUnavailable || needsSelection ? "not-allowed" : "pointer",
      }}
    >
      {buttonText}
    </button>
  );
}
