## AUDIT LOG SERVICE

```typescript
// app/utils/audit-log.server.ts
import { db } from "~/db.server";

export type AuditAction =
  | "QUIZ_CREATED"
  | "QUIZ_UPDATED"
  | "QUIZ_DELETED"
  | "QUIZ_PUBLISHED"
  | "QUIZ_ARCHIVED"
  | "QUESTION_CREATED"
  | "QUESTION_UPDATED"
  | "QUESTION_DELETED"
  | "SETTINGS_UPDATED"
  | "INTEGRATION_CONNECTED"
  | "INTEGRATION_DISCONNECTED"
  | "RESPONSE_DELETED"
  | "RESPONSES_BULK_DELETED"
  | "EXPORT_CREATED"
  | "BILLING_PLAN_CHANGED";

interface LogEntry {
  shop: string;
  actor?: string;
  actorEmail?: string;
  action: AuditAction;
  resource: string;
  resourceId?: string;
  resourceName?: string;
  before?: Record<string, unknown>;
  after?: Record<string, unknown>;
  metadata?: Record<string, unknown>;
}

export async function logAction(entry: LogEntry): Promise<void> {
  try {
    await db.auditLog.create({
      data: {
        shop: entry.shop,
        actor: entry.actor ?? "merchant",
        actorEmail: entry.actorEmail,
        action: entry.action,
        resource: entry.resource,
        resourceId: entry.resourceId,
        resourceName: entry.resourceName,
        changes: entry.before || entry.after
          ? { before: entry.before ?? null, after: entry.after ?? null }
          : undefined,
        metadata: entry.metadata,
      }
    });
  } catch (error) {
    // Audit logging must never block the main operation
    console.error("Audit log failed (non-blocking):", error);
  }
}

// Diff helper — only log what changed
export function diffObjects(
  before: Record<string, unknown>,
  after: Record<string, unknown>
): { before: Record<string, unknown>; after: Record<string, unknown> } {
  const changedBefore: Record<string, unknown> = {};
  const changedAfter: Record<string, unknown> = {};

  for (const key of new Set([...Object.keys(before), ...Object.keys(after)])) {
    if (JSON.stringify(before[key]) !== JSON.stringify(after[key])) {
      changedBefore[key] = before[key];
      changedAfter[key] = after[key];
    }
  }

  return { before: changedBefore, after: changedAfter };
}
