## USAGE IN ACTIONS

```typescript
// In quiz update action
export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const quizId = String(formData.get("quizId"));

  const existing = await db.quiz.findFirst({
    where: { id: quizId, shop: session.shop }
  });
  if (!existing) throw new Response("Not Found", { status: 404 });

  const updated = await db.quiz.update({
    where: { id: quizId },
    data: { title: String(formData.get("title")), status: String(formData.get("status")) as any }
  });

  // Log the change with diff
  const { before, after } = diffObjects(
    { title: existing.title, status: existing.status },
    { title: updated.title, status: updated.status }
  );

  await logAction({
    shop: session.shop,
    action: "QUIZ_UPDATED",
    resource: "Quiz",
    resourceId: quizId,
    resourceName: updated.title,
    before,
    after,
    metadata: { ip: request.headers.get("x-forwarded-for") ?? "unknown" }
  });

  return json({ success: true });
}
