```typescript
// app/components/ConfirmModal.tsx
import { Modal, Text, InlineStack, Icon } from "@shopify/polaris";
import { AlertTriangleIcon } from "@shopify/polaris-icons";
import { useFetcher } from "@remix-run/react";

interface Props {
  open: boolean;
  title: string;
  message: string;
  destructive?: boolean;
  confirmLabel?: string;
  action: string;          // formAction URL
  formData: Record<string, string>;
  onClose: () => void;
}

export function ConfirmModal({
  open, title, message, destructive = false,
  confirmLabel = "Confirm", action, formData, onClose
}: Props) {
  const fetcher = useFetcher();
  const isSubmitting = fetcher.state !== "idle";

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={title}
      primaryAction={{
        content: isSubmitting ? "Processing..." : confirmLabel,
        destructive,
        loading: isSubmitting,
        onAction: () => {
          fetcher.submit(formData, { method: "POST", action });
          onClose();
        },
      }}
      secondaryActions={[{
        content: "Cancel",
        onAction: onClose,
        disabled: isSubmitting,
      }]}
    >
      <Modal.Section>
        {destructive && (
          <InlineStack gap="200" blockAlign="start">
            <Icon source={AlertTriangleIcon} tone="critical" />
            <Text as="p" tone="critical">{message}</Text>
          </InlineStack>
        )}
        {!destructive && <Text as="p">{message}</Text>}
      </Modal.Section>
    </Modal>
  );
}

// Usage
function QuizActions({ quiz }: { quiz: Quiz }) {
  const deleteModal = useModal<{ id: string; title: string }>();

  return (
    <>
      <Button destructive onClick={() => deleteModal.open({ id: quiz.id, title: quiz.title })}>
        Delete
      </Button>

      {deleteModal.isOpen && deleteModal.data && (
        <ConfirmModal
          open
          title={`Delete "${deleteModal.data.title}"?`}
          message="All responses and analytics data will be permanently deleted. This cannot be undone."
          destructive
          confirmLabel="Delete Quiz"
          action="/app/quizzes"
          formData={{ _action: "delete", quizId: deleteModal.data.id }}
          onClose={deleteModal.close}
        />
      )}
    </>
  );
}
