// app/components/EditQuizModal.tsx
import { Modal, FormLayout, TextField, Select, Button } from "@shopify/polaris";
import { useFetcher } from "@remix-run/react";
import { useState, useEffect } from "react";

interface Quiz { id: string; title: string; status: string; description?: string }

interface Props {
  quiz: Quiz;
  open: boolean;
  onClose: () => void;
}

export function EditQuizModal({ quiz, open, onClose }: Props) {
  const fetcher = useFetcher<{ success?: boolean; errors?: Record<string, string> }>();
  const [title, setTitle] = useState(quiz.title);
  const [description, setDescription] = useState(quiz.description ?? "");
  const isDirty = title !== quiz.title || description !== quiz.description;
  const errors = fetcher.data?.errors ?? {};

  // Close after successful save
  useEffect(() => {
    if (fetcher.data?.success) onClose();
  }, [fetcher.data]);

  function handleClose() {
    if (isDirty) {
      if (!window.confirm("You have unsaved changes. Discard them?")) return;
    }
    onClose();
  }

  return (
    <Modal
      open={open}
      onClose={handleClose}
      title="Edit Quiz"
      primaryAction={{
        content: "Save",
        loading: fetcher.state !== "idle",
        onAction: () => {
          fetcher.submit(
            { _action: "update", quizId: quiz.id, title, description },
            { method: "POST", action: "/app/quizzes" }
          );
        },
      }}
      secondaryActions={[{ content: "Cancel", onAction: handleClose }]}
    >
      <Modal.Section>
        <FormLayout>
          <TextField
            label="Title"
            value={title}
            onChange={setTitle}
            error={errors.title}
            autoComplete="off"
            requiredIndicator
          />
          <TextField
            label="Description"
            value={description}
            onChange={setDescription}
            error={errors.description}
            multiline={3}
            autoComplete="off"
          />
        </FormLayout>
      </Modal.Section>
    </Modal>
  );
}
