```typescript
// app/hooks/useWizardModal.ts
import { useState, useCallback } from "react";

export function useWizardModal<TData = Record<string, unknown>>(steps: string[]) {
  const [currentStep, setCurrentStep] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [data, setData] = useState<Partial<TData>>({});

  const open = useCallback(() => { setCurrentStep(0); setIsOpen(true); }, []);
  const close = useCallback(() => { setIsOpen(false); setData({}); }, []);
  const next = useCallback((stepData?: Partial<TData>) => {
    if (stepData) setData(prev => ({ ...prev, ...stepData }));
    setCurrentStep(prev => Math.min(prev + 1, steps.length - 1));
  }, [steps.length]);
  const back = useCallback(() => setCurrentStep(prev => Math.max(prev - 1, 0)), []);

  return {
    isOpen, currentStep, data, open, close, next, back,
    stepName: steps[currentStep],
    isFirst: currentStep === 0,
    isLast: currentStep === steps.length - 1,
    progress: Math.round(((currentStep + 1) / steps.length) * 100),
  };
}

// Usage for quiz creation wizard
