## QUIZ EDITOR REDUCER

```typescript
// app/state/quiz-editor.ts
import { useReducer, useCallback, useMemo } from "react";

export interface QuizEditorQuestion {
  id: string;
  text: string;
  type: string;
  required: boolean;
  order: number;
  answers: Array<{ id: string; text: string; weight: number; order: number }>;
}

export interface QuizEditorState {
  quizId: string;
  title: string;
  description: string;
  status: "DRAFT" | "PUBLISHED" | "ARCHIVED";
  questions: QuizEditorQuestion[];
  selectedQuestionId: string | null;
  isDirty: boolean;
  isSaving: boolean;
  saveError: string | null;
  // Snapshot for dirty detection
  savedSnapshot: string;
}

type Action =
  | { type: "SET_TITLE"; payload: string }
  | { type: "SET_DESCRIPTION"; payload: string }
  | { type: "SET_STATUS"; payload: string }
  | { type: "ADD_QUESTION"; payload: QuizEditorQuestion }
  | { type: "UPDATE_QUESTION"; payload: { id: string; changes: Partial<QuizEditorQuestion> } }
  | { type: "DELETE_QUESTION"; payload: string }
  | { type: "REORDER_QUESTIONS"; payload: { fromIndex: number; toIndex: number } }
  | { type: "SELECT_QUESTION"; payload: string | null }
  | { type: "SAVE_START" }
  | { type: "SAVE_SUCCESS" }
  | { type: "SAVE_ERROR"; payload: string }
  | { type: "RESET_DIRTY" };

function computeSnapshot(state: Omit<QuizEditorState, "isDirty" | "isSaving" | "saveError" | "savedSnapshot" | "selectedQuestionId">): string {
  return JSON.stringify({
    title: state.title,
    description: state.description,
    status: state.status,
    questions: state.questions.map(q => ({ ...q })),
  });
}

export function quizEditorReducer(state: QuizEditorState, action: Action): QuizEditorState {
  let next: QuizEditorState;

  switch (action.type) {
    case "SET_TITLE":
      next = { ...state, title: action.payload };
      break;
    case "SET_DESCRIPTION":
      next = { ...state, description: action.payload };
      break;
    case "SET_STATUS":
      next = { ...state, status: action.payload as QuizEditorState["status"] };
      break;
    case "ADD_QUESTION":
      next = { ...state, questions: [...state.questions, action.payload], selectedQuestionId: action.payload.id };
      break;
    case "UPDATE_QUESTION":
      next = {
        ...state,
        questions: state.questions.map(q =>
          q.id === action.payload.id ? { ...q, ...action.payload.changes } : q
        )
      };
      break;
    case "DELETE_QUESTION":
      next = {
        ...state,
        questions: state.questions.filter(q => q.id !== action.payload).map((q, i) => ({ ...q, order: i })),
        selectedQuestionId: state.selectedQuestionId === action.payload ? null : state.selectedQuestionId,
      };
      break;
    case "REORDER_QUESTIONS": {
      const { fromIndex, toIndex } = action.payload;
      const reordered = [...state.questions];
      const [moved] = reordered.splice(fromIndex, 1);
      reordered.splice(toIndex, 0, moved);
      next = { ...state, questions: reordered.map((q, i) => ({ ...q, order: i })) };
      break;
    }
    case "SELECT_QUESTION":
      return { ...state, selectedQuestionId: action.payload };
    case "SAVE_START":
      return { ...state, isSaving: true, saveError: null };
    case "SAVE_SUCCESS":
      return { ...state, isSaving: false, isDirty: false, savedSnapshot: computeSnapshot(state) };
    case "SAVE_ERROR":
      return { ...state, isSaving: false, saveError: action.payload };
    default:
      return state;
  }

  // Recompute isDirty after any state-changing action
  return { ...next, isDirty: computeSnapshot(next) !== next.savedSnapshot };
}
```

## useQuizEditor HOOK

```typescript
// app/hooks/useQuizEditor.ts
import { useReducer, useCallback, useEffect } from "react";
import { useFetcher, useBeforeUnload } from "@remix-run/react";
import { quizEditorReducer, type QuizEditorState } from "~/state/quiz-editor";

export function useQuizEditor(initialData: Omit<QuizEditorState, "isDirty" | "isSaving" | "saveError" | "savedSnapshot" | "selectedQuestionId">) {
  const snapshot = JSON.stringify({
    title: initialData.title,
    description: initialData.description,
    status: initialData.status,
    questions: initialData.questions,
  });

  const [state, dispatch] = useReducer(quizEditorReducer, {
    ...initialData,
    selectedQuestionId: null,
    isDirty: false,
    isSaving: false,
    saveError: null,
    savedSnapshot: snapshot,
  });

  const fetcher = useFetcher<{ success: boolean; error?: string }>();

  // Warn before browser close/refresh if dirty
  useBeforeUnload(
    useCallback((event) => {
      if (state.isDirty) {
        event.preventDefault();
        return "You have unsaved changes. Are you sure you want to leave?";
      }
    }, [state.isDirty])
  );

  // Handle save response
  useEffect(() => {
    if (fetcher.data?.success) dispatch({ type: "SAVE_SUCCESS" });
    if (fetcher.data?.error) dispatch({ type: "SAVE_ERROR", payload: fetcher.data.error });
  }, [fetcher.data]);

  const save = useCallback(() => {
    dispatch({ type: "SAVE_START" });
    fetcher.submit(
      { _action: "saveQuiz", data: JSON.stringify(state) },
      { method: "POST", action: `/app/quizzes/${state.quizId}/edit` }
    );
  }, [state, fetcher]);

  return { state, dispatch, save };
}
```

## UNSAVED CHANGES NAVIGATION BLOCKER

```typescript
// app/components/UnsavedChangesBar.tsx
import { InlineStack, Button, Text, Banner } from "@shopify/polaris";
import { useBlocker } from "@remix-run/react";

interface Props {
  isDirty: boolean;
  onSave: () => void;
  onDiscard: () => void;
  isSaving: boolean;
}

export function UnsavedChangesBar({ isDirty, onSave, onDiscard, isSaving }: Props) {
  // Block React Router navigation when dirty
  const blocker = useBlocker(({ currentLocation, nextLocation }) =>
    isDirty && currentLocation.pathname !== nextLocation.pathname
  );

  if (blocker.state === "blocked") {
    return (
      <Banner
        title="You have unsaved changes"
        tone="warning"
        action={{ content: "Save changes", onAction: () => { onSave(); blocker.reset(); } }}
        secondaryAction={{ content: "Discard and leave", onAction: () => blocker.proceed() }}
        onDismiss={blocker.reset}
      />
    );
  }

  if (!isDirty) return null;

  return (
    <div style={{ position: "sticky", top: 0, zIndex: 100, background: "#fff3cd", padding: "8px 16px" }}>
      <InlineStack align="space-between" blockAlign="center">
        <Text as="span" fontWeight="medium">Unsaved changes</Text>
        <InlineStack gap="200">
          <Button size="slim" onClick={onDiscard} disabled={isSaving}>Discard</Button>
          <Button size="slim" variant="primary" onClick={onSave} loading={isSaving}>Save</Button>
        </InlineStack>
      </InlineStack>
    </div>
  );
}
