// Simple answer selection for quiz preview mode
import { useState } from "react";

export function useAnswerSelection(questions: QuizEditorQuestion[]) {
  const [selections, setSelections] = useState<Record<string, string[]>>({});

  function selectAnswer(questionId: string, answerId: string, multiple: boolean) {
    setSelections(prev => ({
      ...prev,
      [questionId]: multiple
        ? prev[questionId]?.includes(answerId)
          ? prev[questionId].filter(id => id !== answerId)
          : [...(prev[questionId] ?? []), answerId]
        : [answerId]
    }));
  }

  const completedCount = Object.keys(selections).length;
  const totalRequired = questions.filter(q => q.required).length;
  const canSubmit = completedCount >= totalRequired;

  return { selections, selectAnswer, completedCount, totalRequired, canSubmit };
}
