## GRAPHQL INVENTORY QUERY

```typescript
// app/utils/inventory.server.ts
import type { AdminApiContext } from "@shopify/shopify-app-remix/server";

export interface InventoryStatus {
  variantId: string;
  productId: string;
  availableForSale: boolean;
  inventoryQuantity: number;
  inventoryPolicy: "DENY" | "CONTINUE";   // CONTINUE = allows oversell
}

export async function getProductInventory(
  admin: AdminApiContext,
  productGids: string[]
): Promise<Map<string, InventoryStatus[]>> {
  if (productGids.length === 0) return new Map();

  // Batch up to 50 products per query
  const chunks = chunkArray(productGids, 50);
  const results = new Map<string, InventoryStatus[]>();

  for (const chunk of chunks) {
    const query = chunk.map((gid, i) => `
      p${i}: product(id: "${gid}") {
        id
        variants(first: 100) {
          edges {
            node {
              id
              availableForSale
              inventoryQuantity
              inventoryPolicy
            }
          }
        }
      }
    `).join("\n");

    const resp = await admin.graphql(`#graphql query { ${query} }`);
    const { data } = await resp.json();

    for (let i = 0; i < chunk.length; i++) {
      const product = data[`p${i}`];
      if (!product) continue;

      const variants: InventoryStatus[] = product.variants.edges.map(({ node }: any) => ({
        variantId: node.id,
        productId: product.id,
        availableForSale: node.availableForSale,
        inventoryQuantity: node.inventoryQuantity ?? 0,
        inventoryPolicy: node.inventoryPolicy,
      }));

      results.set(product.id, variants);
    }
  }

  return results;
}

function chunkArray<T>(arr: T[], size: number): T[][] {
  return Array.from({ length: Math.ceil(arr.length / size) }, (_, i) =>
    arr.slice(i * size, i * size + size)
  );
}
```

## INVENTORY WEBHOOK SYNC

```typescript
// app/routes/webhooks.inventory.update.tsx
import type { ActionFunctionArgs } from "@remix-run/node";
import { authenticate } from "~/shopify.server";
import { db } from "~/db.server";

// Register in shopify.app.toml:
// [[webhooks.subscriptions]]
// topics = ["inventory_levels/update"]

export async function action({ request }: ActionFunctionArgs) {
  const { shop, payload } = await authenticate.webhook(request);

  const update = payload as {
    inventory_item_id: number;
    available: number;
    updated_at: string;
  };

  // Find variants linked to this inventory item
  const inventoryItemGid = `gid://shopify/InventoryItem/${update.inventory_item_id}`;

  // Update cached inventory in ProductMapping
  await db.productMapping.updateMany({
    where: {
      shop,
      inventoryItemId: inventoryItemGid,
    },
    data: {
      inventoryQuantity: Math.max(0, update.available),
      availableForSale: update.available > 0,
      inventorySyncedAt: new Date(),
    }
  });

  return new Response("OK");
}
