## FILTER OUT-OF-STOCK FROM RECOMMENDATIONS

```typescript
// app/utils/recommendation-filter.server.ts
import { db } from "~/db.server";

export async function filterAvailableProducts(
  shop: string,
  productIds: string[],
  options: {
    excludeOutOfStock?: boolean;
    minimumInventory?: number;
  } = {}
): Promise<string[]> {
  const { excludeOutOfStock = true, minimumInventory = 0 } = options;

  if (!excludeOutOfStock) return productIds;

  const mappings = await db.productMapping.findMany({
    where: {
      shop,
      shopifyProductId: { in: productIds },
    },
    select: {
      shopifyProductId: true,
      availableForSale: true,
      inventoryQuantity: true,
      inventoryPolicy: true,
    }
  });

  const availableIds = new Set<string>();
  for (const mapping of mappings) {
    const meetsInventory = mapping.inventoryQuantity >= minimumInventory;
    const canSell = mapping.availableForSale || mapping.inventoryPolicy === "CONTINUE";
    if (meetsInventory && canSell) {
      availableIds.add(mapping.shopifyProductId);
    }
  }

  // Products not in DB are assumed available (conservative)
  return productIds.filter(id => !mappings.find(m => m.shopifyProductId === id) || availableIds.has(id));
}
```

