  showCount?: boolean;
  lowStockThreshold?: number;
}

export function StockStatus({
  available,
  quantity,
  policy = "DENY",
  showCount = false,
  lowStockThreshold = 5
}: Props) {
  const canOrder = available || policy === "CONTINUE";

  if (!canOrder) {
    return (
      <span style={{ color: "#D72C0D", fontSize: 13, fontWeight: 500 }}>
        Sold Out
      </span>
    );
  }

  if (quantity > 0 && quantity <= lowStockThreshold) {
    return (
      <span style={{ color: "#F49342", fontSize: 13, fontWeight: 500 }}>
        Low Stock {showCount ? `(${quantity} left)` : ""}
      </span>
    );
  }

  return (
    <span style={{ color: "#00A651", fontSize: 13, fontWeight: 500 }}>
      In Stock {showCount && quantity > 0 ? `(${quantity})` : ""}
    </span>
  );
}
