## BULK INVENTORY REFRESH JOB

```typescript
// app/utils/inventory-refresh.server.ts
export async function refreshAllProductInventory(
  shop: string,
  admin: AdminApiContext
): Promise<{ synced: number; errors: number }> {
  const mappings = await db.productMapping.findMany({
    where: { shop },
    select: { shopifyProductId: true }
  });

  const productIds = mappings.map(m => m.shopifyProductId);
  const inventoryMap = await getProductInventory(admin, productIds);

  let synced = 0;
  let errors = 0;

  for (const [productId, variants] of inventoryMap) {
    try {
      const totalQty = variants.reduce((sum, v) => sum + v.inventoryQuantity, 0);
      const anyAvailable = variants.some(v => v.availableForSale);

      await db.productMapping.updateMany({
        where: { shop, shopifyProductId: productId },
        data: {
          inventoryQuantity: totalQty,
          availableForSale: anyAvailable,
          inventorySyncedAt: new Date(),
        }
      });
      synced++;
    } catch {
      errors++;
    }
  }

  return { synced, errors };
}
```

