## DISCOUNT CODE VALIDATION (Admin API)

```typescript
// app/utils/discount.server.ts
import type { AdminApiContext } from "@shopify/shopify-app-remix/server";

export interface DiscountValidationResult {
  valid: boolean;
  code: string;
  type: "PERCENTAGE" | "FIXED_AMOUNT" | "FREE_SHIPPING" | null;
  value: number;
  minOrderAmount?: number;
  usageLimit?: number;
  usageCount?: number;
  startsAt?: string;
  endsAt?: string;
  expired: boolean;
  exhausted: boolean;
  error?: string;
}

export async function validateDiscountCode(
  admin: AdminApiContext,
  code: string
): Promise<DiscountValidationResult> {
  const resp = await admin.graphql(
    `#graphql
    query ValidateDiscount($code: String!) {
      codeDiscountNodeByCode(code: $code) {
        id
        codeDiscount {
          ... on DiscountCodeBasic {
            title
            startsAt
            endsAt
            usageLimit
            asyncUsageCount
            status
            customerGets {
              value {
                ... on DiscountPercentage { percentage }
                ... on DiscountAmount { amount { amount currencyCode } }
              }
            }
            minimumRequirement {
              ... on DiscountMinimumSubtotal {
                greaterThanOrEqualToSubtotal { amount currencyCode }
              }
            }
          }
        }
      }
    }`,
    { variables: { code: code.trim().toUpperCase() } }
  );

  const { data } = await resp.json();
  const node = data?.codeDiscountNodeByCode;

  if (!node) {
    return { valid: false, code, type: null, value: 0, expired: false, exhausted: false, error: "Discount code not found" };
  }

  const discount = node.codeDiscount;
  const now = new Date();
  const expired = discount.endsAt ? new Date(discount.endsAt) < now : false;
  const exhausted = discount.usageLimit !== null && discount.asyncUsageCount >= discount.usageLimit;

  let type: DiscountValidationResult["type"] = null;
  let value = 0;

  if (discount.customerGets?.value) {
    const val = discount.customerGets.value;
    if ("percentage" in val) {
      type = "PERCENTAGE";
      value = Math.round(val.percentage * 100);
    } else if ("amount" in val) {
      type = "FIXED_AMOUNT";
      value = parseFloat(val.amount.amount);
    }
  }

  const minOrderAmount = discount.minimumRequirement?.greaterThanOrEqualToSubtotal
    ? parseFloat(discount.minimumRequirement.greaterThanOrEqualToSubtotal.amount)
    : undefined;

  return {
    valid: !expired && !exhausted && discount.status === "ACTIVE",
    code: code.trim().toUpperCase(),
    type,
    value,
    minOrderAmount,
    usageLimit: discount.usageLimit,
    usageCount: discount.asyncUsageCount,
    startsAt: discount.startsAt,
    endsAt: discount.endsAt,
    expired,
    exhausted,
    error: expired ? "This discount code has expired" : exhausted ? "This discount code has reached its usage limit" : undefined,
  };
}
```

## AUTO-GENERATE DISCOUNT PER QUIZ COMPLETION

```typescript
// app/utils/discount-generator.server.ts
export async function createQuizCompletionDiscount(
  admin: AdminApiContext,
  options: {
    percentage: number;
    expiresInDays?: number;
    prefix?: string;
    maxUses?: number;
  }
): Promise<{ code: string; discountGid: string }> {
  const { percentage, expiresInDays = 7, prefix = "QUIZ", maxUses = 1 } = options;

  const code = `${prefix}${Math.round(percentage * 100)}-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
  const endsAt = expiresInDays
    ? new Date(Date.now() + expiresInDays * 24 * 60 * 60 * 1000).toISOString()
    : undefined;

  const resp = await admin.graphql(
    `#graphql
    mutation discountCodeBasicCreate($basicCodeDiscount: DiscountCodeBasicInput!) {
      discountCodeBasicCreate(basicCodeDiscount: $basicCodeDiscount) {
        codeDiscountNode { id }
        userErrors { field message code }
      }
    }`,
    {
      variables: {
        basicCodeDiscount: {
          title: `QuizSnap — ${Math.round(percentage * 100)}% Off`,
          code,
          startsAt: new Date().toISOString(),
          endsAt,
          usageLimit: maxUses,
          customerGets: {
            value: { percentage },
            items: { allItems: true }
          },
          customerSelection: { allCustomers: true },
        }
      }
    }
  );

  const { data } = await resp.json();
  const errors = data.discountCodeBasicCreate.userErrors;

  if (errors.length > 0) {
    throw new Error(`Failed to create discount: ${errors[0].message}`);
  }

  return {
    code,
    discountGid: data.discountCodeBasicCreate.codeDiscountNode.id,
  };
}
