// app/utils/notifications.server.ts
import { db } from "~/db.server";

export type NotificationType = "NEW_RESPONSE" | "HIGH_VALUE_LEAD" | "DAILY_DIGEST" | "SYSTEM";

interface CreateNotificationInput {
  shop: string;
  type: NotificationType;
  title: string;
  body: string;
  link?: string;
  metadata?: Record<string, unknown>;
}

export async function createNotification(input: CreateNotificationInput): Promise<void> {
  // Check preferences before creating
  const prefs = await db.notificationPreferences.findUnique({ where: { shop: input.shop } });

  const prefKey = input.type === "NEW_RESPONSE" ? "newResponse"
    : input.type === "HIGH_VALUE_LEAD" ? "highValueLead"
    : input.type === "DAILY_DIGEST" ? "dailyDigest"
    : null;

  if (prefKey && prefs && !(prefs as any)[prefKey]) return; // Notification disabled

  await db.notification.create({ data: input });
}

export async function getUnreadCount(shop: string): Promise<number> {
  return db.notification.count({ where: { shop, isRead: false } });
}

export async function getNotifications(
  shop: string,
  limit = 20,
  unreadOnly = false
): Promise<Notification[]> {
  return db.notification.findMany({
    where: { shop, ...(unreadOnly && { isRead: false }) },
    orderBy: { createdAt: "desc" },
    take: limit,
  }) as Promise<Notification[]>;
}

export async function markAsRead(shop: string, notificationIds: string[]): Promise<void> {
  await db.notification.updateMany({
    where: { shop, id: { in: notificationIds } },
    data: { isRead: true, readAt: new Date() }
  });
}

export async function markAllAsRead(shop: string): Promise<void> {
  await db.notification.updateMany({
    where: { shop, isRead: false },
    data: { isRead: true, readAt: new Date() }
  });
}

// Cleanup: delete notifications older than 30 days
export async function cleanupOldNotifications(shop: string): Promise<void> {
  const cutoff = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
  await db.notification.deleteMany({ where: { shop, createdAt: { lt: cutoff } } });
}
