    NEW_RESPONSE: "📋", HIGH_VALUE_LEAD: "⭐", DAILY_DIGEST: "📊", SYSTEM: "🔧"
  };

  return (
    <Box
      padding="300"
      background={notification.isRead ? undefined : "bg-surface-active"}
      borderBlockEndWidth="025"
      borderColor="border"
    >
