## KLAVIYO API CLIENT (No SDK — Direct Fetch)

```typescript
// app/utils/klaviyo.server.ts
const KLAVIYO_API_VERSION = "2024-02-15";
const KLAVIYO_BASE = "https://a.klaviyo.com/api";

interface KlaviyoRequestOptions {
  method?: "GET" | "POST" | "PATCH" | "DELETE";
  body?: unknown;
}

async function klaviyoRequest(
  apiKey: string,
  endpoint: string,
  options: KlaviyoRequestOptions = {}
): Promise<{ ok: boolean; status: number; data?: unknown; error?: string }> {
  try {
    const resp = await fetch(`${KLAVIYO_BASE}/${endpoint}`, {
      method: options.method ?? "GET",
      headers: {
        "Authorization": `Klaviyo-API-Key ${apiKey}`,
        "Content-Type": "application/json",
        "revision": KLAVIYO_API_VERSION,
        "Accept": "application/json",
      },
      body: options.body ? JSON.stringify(options.body) : undefined,
    });

    if (resp.status === 204) return { ok: true, status: 204 };

    const data = await resp.json();
    if (!resp.ok) {
      const message = data.errors?.[0]?.detail ?? `Klaviyo error ${resp.status}`;
      return { ok: false, status: resp.status, error: message };
    }

    return { ok: true, status: resp.status, data };
  } catch (err) {
    return { ok: false, status: 0, error: "Network error reaching Klaviyo" };
  }
}

export async function validateKlaviyoApiKey(apiKey: string): Promise<boolean> {
  const result = await klaviyoRequest(apiKey, "lists?page[size]=1");
  return result.ok;
}
