## TRACK QUIZ COMPLETION EVENT

```typescript
// app/utils/klaviyo.server.ts (continued)

interface QuizCompletionEventData {
  email: string;
  firstName?: string;
  lastName?: string;
  quizTitle: string;
  quizId: string;
  resultPageTitle: string;
  score: number;
  recommendedProducts: Array<{ title: string; url: string; imageUrl?: string; price: string }>;
  emailCaptured: boolean;
  completedAt: string;
}

export async function trackQuizCompletion(
  apiKey: string,
  data: QuizCompletionEventData
): Promise<{ success: boolean; error?: string }> {
  const result = await klaviyoRequest(apiKey, "events", {
    method: "POST",
    body: {
      data: {
        type: "event",
        attributes: {
          properties: {
            quiz_id: data.quizId,
            quiz_title: data.quizTitle,
            result_page: data.resultPageTitle,
            quiz_score: data.score,
            email_captured: data.emailCaptured,
            top_product: data.recommendedProducts[0]?.title ?? null,
            recommended_products: data.recommendedProducts.map(p => ({
              title: p.title,
              url: p.url,
              image: p.imageUrl,
              price: p.price,
            })),
            recommended_count: data.recommendedProducts.length,
            completed_at: data.completedAt,
          },
          metric: {
            data: {
              type: "metric",
              attributes: { name: "Quiz Completed" }
            }
          },
          profile: {
            data: {
              type: "profile",
              attributes: {
                email: data.email,
                first_name: data.firstName ?? null,
                last_name: data.lastName ?? null,
                properties: {
                  last_quiz_result: data.resultPageTitle,
                  last_quiz_score: data.score,
                  last_quiz_title: data.quizTitle,
                  last_quiz_completed: data.completedAt,
                }
              }
            }
          }
        }
      }
    }
  });

  if (!result.ok) {
    console.error("Klaviyo event tracking failed:", result.error);
    return { success: false, error: result.error };
  }

  return { success: true };
}
