// In the quiz completion handler (storefront or webhook)
async function handleQuizCompletion(shop: string, responseData: QuizResponseData) {
  // 1. Save to DB first (blocking)
  const response = await saveQuizResponse(shop, responseData);

  // 2. Fire Klaviyo in background (non-blocking)
  const integration = await db.integration.findFirst({
    where: { shop, type: "KLAVIYO", enabled: true }
  });

  if (integration?.apiKey && responseData.email) {
    // Don't await — non-blocking, fire and forget
    trackQuizCompletion(integration.apiKey, {
      email: responseData.email,
      quizTitle: responseData.quizTitle,
      quizId: responseData.quizId,
      resultPageTitle: responseData.resultPage,
      score: responseData.score,
      recommendedProducts: responseData.products,
      emailCaptured: true,
      completedAt: new Date().toISOString(),
    }).catch(err => console.error("Klaviyo non-blocking error:", err));

    // Subscribe to list if configured
    if (integration.listId) {
      subscribeToKlaviyoList(integration.apiKey, integration.listId, {
