```typescript
// app/utils/shopify-flow.server.ts
import type { AdminApiContext } from "@shopify/shopify-app-remix/server";

const FLOW_TRIGGER_MUTATION = `#graphql
  mutation flowTriggerReceive($handle: String!, $payload: JSON!) {
    flowTriggerReceive(handle: $handle, payload: $payload) {
      userErrors {
        field
        message
      }
    }
  }
`;

interface QuizCompletedPayload {
  quiz_id: string;
  quiz_title: string;
  result_page: string;
  quiz_score: number;
  customer_email?: string;
  recommended_product_ids: string;    // comma-separated GIDs
}

interface HighValueLeadPayload {
  customer_email: string;
  quiz_score: number;
  quiz_id: string;
  quiz_title: string;
  top_product_id: string;
}

interface EmailCapturedPayload {
  customer_email: string;
  quiz_title: string;
  quiz_id: string;
}

export async function triggerQuizCompleted(
  admin: AdminApiContext,
  payload: QuizCompletedPayload
): Promise<void> {
  await sendFlowTrigger(admin, "quiz-completed", payload);
}

export async function triggerHighValueLead(
  admin: AdminApiContext,
  payload: HighValueLeadPayload
): Promise<void> {
  await sendFlowTrigger(admin, "high-value-lead", payload);
}

export async function triggerEmailCaptured(
  admin: AdminApiContext,
  payload: EmailCapturedPayload
): Promise<void> {
  await sendFlowTrigger(admin, "email-captured", payload);
}

async function sendFlowTrigger(
  admin: AdminApiContext,
  handle: string,
  payload: Record<string, unknown>
): Promise<void> {
  try {
    const resp = await admin.graphql(FLOW_TRIGGER_MUTATION, {
      variables: { handle, payload }
    });
    const { data } = await resp.json();

    const errors = data?.flowTriggerReceive?.userErrors ?? [];
    if (errors.length > 0) {
      // Log but don't throw — Flow triggers are best-effort
      console.error(`Flow trigger "${handle}" userErrors:`, errors);
    }
  } catch (err) {
    // Never block quiz completion for Flow trigger failures
    console.error(`Flow trigger "${handle}" failed (non-blocking):`, err);
  }
}
```

