## IN-MEMORY SLIDING WINDOW RATE LIMITER

```typescript
// app/utils/rate-limiter.server.ts

interface RateLimitEntry {
  requests: number[];   // Timestamps of requests in the current window
  blocked: boolean;
}

// Simple in-memory store — works for single-process deployments
// For multi-instance: swap Map for Redis (Upstash recommended for Shopify)
const store = new Map<string, RateLimitEntry>();

// Cleanup expired entries every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of store.entries()) {
    // Remove if all requests are outside the max window (1 hour)
    if (entry.requests.every(t => now - t > 3_600_000)) {
      store.delete(key);
    }
  }
}, 5 * 60 * 1000);

export interface RateLimitConfig {
  windowMs: number;     // Window size in ms (e.g., 60_000 = 1 minute)
  maxRequests: number;  // Max requests per window
  keyPrefix?: string;
}

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetAt: number;      // Unix timestamp when window resets
  retryAfter?: number;  // Seconds to wait if blocked
}

export function checkRateLimit(
  identifier: string,
  config: RateLimitConfig
): RateLimitResult {
  const key = `${config.keyPrefix ?? "rl"}:${identifier}`;
  const now = Date.now();
  const windowStart = now - config.windowMs;

  const entry = store.get(key) ?? { requests: [], blocked: false };

  // Remove requests outside the sliding window
  entry.requests = entry.requests.filter(t => t > windowStart);

  if (entry.requests.length >= config.maxRequests) {
    const oldestInWindow = entry.requests[0];
    const resetAt = oldestInWindow + config.windowMs;
    const retryAfter = Math.ceil((resetAt - now) / 1000);

    store.set(key, entry);
    return { allowed: false, remaining: 0, resetAt, retryAfter };
  }

  entry.requests.push(now);
  store.set(key, entry);

  const resetAt = (entry.requests[0] ?? now) + config.windowMs;
  const remaining = config.maxRequests - entry.requests.length;

  return { allowed: true, remaining, resetAt };
}
```

