## SHOPIFY API RATE LIMIT HANDLER

```typescript
// app/utils/shopify-throttle.server.ts
export async function withShopifyThrottle<T>(
  fn: () => Promise<T>,
  maxRetries = 3
): Promise<T> {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (err: any) {
      const isThrottled =
        err?.message?.includes("THROTTLED") ||
        err?.extensions?.code === "THROTTLED";

      if (!isThrottled || attempt === maxRetries - 1) throw err;

      const backoffMs = Math.pow(2, attempt) * 1000 + Math.random() * 500;
      console.warn(`Shopify API throttled, retrying in ${Math.round(backoffMs)}ms (attempt ${attempt + 1})`);
      await new Promise(r => setTimeout(r, backoffMs));
    }
  }
  throw new Error("Max retries exceeded");
}
```

## TRUSTED SOURCE BYPASS (Internal Services)

```typescript
// app/utils/rate-limit-bypass.server.ts
import crypto from "crypto";

const INTERNAL_SECRET = process.env.INTERNAL_API_SECRET ?? "";

export function generateBypassToken(payload: string): string {
  return crypto.createHmac("sha256", INTERNAL_SECRET).update(payload).digest("hex");
}

export function isTrustedSource(request: Request): boolean {
  const token = request.headers.get("x-internal-token");
  const timestamp = request.headers.get("x-internal-timestamp");
  if (!token || !timestamp) return false;

  // Reject stale tokens (>5 minutes)
  if (Date.now() - Number(timestamp) > 5 * 60 * 1000) return false;

  const expected = generateBypassToken(timestamp);
  return crypto.timingSafeEqual(Buffer.from(token), Buffer.from(expected));
}
```

