## UPSELL ALGORITHM

```typescript
// app/utils/upsell-algorithm.server.ts
import { db } from "~/db.server";

interface ProductScore {
  productId: string;
  score: number;
  title: string;
  price: number;
  imageUrl?: string;
  collectionIds: string[];
}

interface UpsellResult {
  type: "upsell" | "cross-sell" | "bundle";
  products: Array<{
    id: string;
    title: string;
    price: string;
    imageUrl?: string;
    reason: string;
  }>;
  bundleDiscount?: number;     // e.g. 0.10 = 10% off bundle
  bundleTitle?: string;
}

export async function computeUpsells(
  shop: string,
  primaryProductIds: string[],
  allProductScores: ProductScore[],
  options: {
    maxUpsells?: number;
    bundleDiscountPct?: number;
    enableCrossSell?: boolean;
  } = {}
): Promise<UpsellResult[]> {
  const {
    maxUpsells = 3,
    bundleDiscountPct = 0.10,
    enableCrossSell = true
  } = options;

  const primarySet = new Set(primaryProductIds);
  const results: UpsellResult[] = [];

  // 1. Upsell: High-scored products NOT in primary recommendations
  const upsellCandidates = allProductScores
    .filter(p => !primarySet.has(p.productId) && p.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, maxUpsells);

  if (upsellCandidates.length > 0) {
    results.push({
      type: "upsell",
      products: upsellCandidates.map(p => ({
        id: p.productId,
        title: p.title,
        price: p.price.toFixed(2),
        imageUrl: p.imageUrl,
        reason: "Also matches your profile",
      })),
    });
  }

  // 2. Cross-sell: Products from shared collections
  if (enableCrossSell && primaryProductIds.length > 0) {
    const primaryCollections = new Set(
      allProductScores
        .filter(p => primarySet.has(p.productId))
        .flatMap(p => p.collectionIds)
    );

    const crossSellCandidates = allProductScores
      .filter(p =>
        !primarySet.has(p.productId) &&
        !upsellCandidates.some(u => u.productId === p.productId) &&
        p.collectionIds.some(c => primaryCollections.has(c))
      )
      .slice(0, 2);

    if (crossSellCandidates.length > 0) {
      results.push({
        type: "cross-sell",
        products: crossSellCandidates.map(p => ({
          id: p.productId,
          title: p.title,
          price: p.price.toFixed(2),
          imageUrl: p.imageUrl,
          reason: "Frequently paired together",
        })),
      });
    }
  }

  // 3. Bundle: Top primary + top upsell with discount
  if (primaryProductIds.length >= 1 && upsellCandidates.length >= 1 && bundleDiscountPct > 0) {
    const bundleProducts = [
      ...allProductScores.filter(p => p.productId === primaryProductIds[0]),
      upsellCandidates[0],
    ];

    if (bundleProducts.length >= 2) {
      const totalPrice = bundleProducts.reduce((s, p) => s + p.price, 0);
      const discountedPrice = totalPrice * (1 - bundleDiscountPct);

      results.push({
        type: "bundle",
        products: bundleProducts.map(p => ({
          id: p.productId,
          title: p.title,
          price: p.price.toFixed(2),
          imageUrl: p.imageUrl,
          reason: "Bundle deal",
        })),
        bundleDiscount: bundleDiscountPct,
        bundleTitle: `Bundle & Save ${Math.round(bundleDiscountPct * 100)}%`,
      });
    }
  }

  return results;
}
```

