  const [addingBundle, setAddingBundle] = useState(false);
  const [bundleAdded, setBundleAdded] = useState(false);

  const sectionTitle = type === "bundle"
    ? bundleTitle ?? "Bundle & Save"
    : type === "cross-sell"
    ? "Frequently Paired Together"
    : "You Might Also Like";

  const totalBundlePrice = products.reduce((s, p) => s + parseFloat(p.price), 0);
  const discountedBundlePrice = bundleDiscount
    ? totalBundlePrice * (1 - bundleDiscount)
    : totalBundlePrice;

  async function handleAddBundle() {
    if (!onAddBundle) return;
    setAddingBundle(true);
    try {
      await onAddBundle(products.map(p => p.id));
      setBundleAdded(true);
      setTimeout(() => setBundleAdded(false), 3000);
    } finally {
      setAddingBundle(false);
    }
  }

  return (
    <div style={{
      border: "1.5px solid #e1e3e5",
      borderRadius: 8,
      padding: "16px 20px",
      marginTop: 24,
      background: type === "bundle" ? "#f9fafb" : "white",
    }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 15, fontWeight: 600, color: "#202223" }}>
        {sectionTitle}
        {bundleDiscount && (
          <span style={{ marginLeft: 8, background: "#00A651", color: "white", borderRadius: 12, padding: "2px 8px", fontSize: 12 }}>
            {Math.round(bundleDiscount * 100)}% OFF
          </span>
        )}
      </h3>

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
        {products.map((product, i) => (
          <div key={product.id} style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {i > 0 && <span style={{ color: "#6d7175", fontSize: 18 }}>+</span>}
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              {product.imageUrl && (
                <img src={product.imageUrl} alt={product.title} width={48} height={48}
                  style={{ borderRadius: 4, objectFit: "cover" }} />
              )}
              <div>
                <p style={{ margin: 0, fontSize: 13, fontWeight: 500 }}>{product.title}</p>
                <p style={{ margin: 0, fontSize: 13, color: "#6d7175" }}>${product.price}</p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {type === "bundle" && bundleDiscount && (
        <div style={{ marginTop: 12, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <span style={{ textDecoration: "line-through", color: "#6d7175", fontSize: 14 }}>
              ${totalBundlePrice.toFixed(2)}
            </span>
            {" "}
            <span style={{ fontWeight: 700, fontSize: 16, color: "#202223" }}>
              ${discountedBundlePrice.toFixed(2)}
            </span>
          </div>
          <button
            onClick={handleAddBundle}
            disabled={addingBundle || bundleAdded}
            style={{
              background: bundleAdded ? "#00A651" : "#5C6AC4",
              color: "white", border: "none",
              borderRadius: 6, padding: "8px 16px",
              fontWeight: 600, fontSize: 14, cursor: "pointer",
            }}
          >
            {addingBundle ? "Adding..." : bundleAdded ? "Added to Cart!" : "Add Bundle to Cart"}
          </button>
        </div>
      )}

      {type !== "bundle" && (
        <div style={{ marginTop: 12 }}>
          <p style={{ margin: 0, fontSize: 12, color: "#6d7175" }}>{products[0]?.reason}</p>
        </div>
      )}
    </div>
  );
}
