## ADD BUNDLE TO CART

```typescript
// app/utils/storefront-cart.ts
export async function addBundleToCart(
  storeDomain: string,
  productIds: string[],     // Shopify variant IDs (numeric strings)
  discountCode?: string
): Promise<boolean> {
  const items = productIds.map(id => ({
    id: id.split("/").pop(),  // Strip GID prefix if present
    quantity: 1,
  }));

  const resp = await fetch(`https://${storeDomain}/cart/add.js`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ items }),
  });

  if (!resp.ok) return false;

  // Redirect to cart with discount applied if provided
  if (discountCode) {
    window.location.href = `https://${storeDomain}/cart?discount=${discountCode}`;
  }

  return true;
}
